"""Replay service for dead-letter queue entries."""

from dataclasses import dataclass
from delivery_ledger import DeliveryLedgerRecord
from message_models import MessageModelsRecord
from replay_policy import ReplayPolicyRecord


@dataclass
class DeadLetterEntry:
    message_id: str
    payload: dict
    reason: str
    replay_token: str
    attempts: int = 0


class ReplayService:
    def __init__(self, ledger: DeliveryLedgerRecord, policy: ReplayPolicyRecord) -> None:
        self.ledger = ledger
        self.policy = policy

    def replay(self, entry: DeadLetterEntry, token: str, dispatcher) -> dict:
        if token != entry.replay_token:
            return {"ok": False, "message_id": entry.message_id, "status": "denied"}
        if entry.attempts >= self.policy.metadata.get("max_attempts", 3):
            return {"ok": False, "message_id": entry.message_id, "status": "exhausted"}
        result = dispatcher(MessageModelsRecord(entry.message_id, metadata=entry.payload))
        entry.attempts += 1
        if result:
            self.ledger.metadata[entry.message_id] = "processed"
            return {"ok": True, "message_id": entry.message_id, "status": "replayed"}
        return {"ok": False, "message_id": entry.message_id, "status": "failed"}


def replay_dead_letter(entry: DeadLetterEntry, token: str, ledger: DeliveryLedgerRecord, dispatcher) -> dict:
    policy = ReplayPolicyRecord("default", metadata={"max_attempts": 3})
    return ReplayService(ledger, policy).replay(entry, token, dispatcher)

# Operational helpers used by this challenge domain.
REPLAY_SERVICE_DOMAIN_TERMS = ('replay', 'message', 'ledger', 'dispatch')

class ReplayServiceLedger:
    """In-memory notes for local operational decisions."""

    def __init__(self, owner="system", metadata=None):
        self.owner = owner
        self.metadata = dict(metadata or {})
        self.events = []

    def record(self, event, **details):
        item = {"event": str(event), "details": dict(details)}
        self.events.append(item)
        self.metadata[item["event"]] = self.metadata.get(item["event"], 0) + 1
        return item

    def snapshot(self):
        return {"owner": self.owner, "metadata": dict(self.metadata), "events": list(self.events)}

def replay_service_compact_metadata(metadata):
    """Return public replay metadata without empty values."""
    clean = {}
    for name, value in dict(metadata or {}).items():
        if value in (None, "", [], {}):
            continue
        clean[str(name)] = value
    return clean

def replay_service_merge_context(base, extra):
    """Merge message context without mutating caller-owned dictionaries."""
    merged = replay_service_compact_metadata(base)
    for name, value in dict(extra or {}).items():
        if value is not None:
            merged[str(name)] = value
    return merged

def replay_service_labels(records, key="name"):
    """Extract labels for ledger diagnostics."""
    labels = []
    for record in records or []:
        value = record.get(key) if isinstance(record, dict) else getattr(record, key, None)
        if value is not None:
            labels.append(str(value))
    return labels

def replay_service_group_by_status(records, key="status"):
    """Group dispatch records for operator summaries."""
    grouped = {}
    for record in records or []:
        status = record.get(key, "unknown") if isinstance(record, dict) else getattr(record, key, "unknown")
        grouped.setdefault(str(status), []).append(record)
    return grouped

def replay_service_summary(records, key="status"):
    """Count replay service records by status."""
    return {name: len(items) for name, items in replay_service_group_by_status(records, key).items()}

