from delivery_ledger import DeliveryLedgerRecord
from replay_service import DeadLetterEntry, ReplayService, replay_dead_letter
from replay_policy import ReplayPolicyRecord


def entry(message_id="m1", attempts=0):
    return DeadLetterEntry(message_id, {"invoice_id": "i1"}, "timeout", "token-1", attempts)


def test_valid_dead_letter_replays_successfully():
    result = replay_dead_letter(entry(), "token-1", DeliveryLedgerRecord("ledger"), lambda msg: True)
    assert result["status"] == "replayed"


def test_replay_rejects_bad_token():
    result = replay_dead_letter(entry(), "wrong", DeliveryLedgerRecord("ledger"), lambda msg: True)
    assert result == {"ok": False, "message_id": "m1", "status": "denied"}


def test_replay_skips_already_processed_message():
    ledger = DeliveryLedgerRecord("ledger", metadata={"m1": "processed"})
    result = replay_dead_letter(entry(), "token-1", ledger, lambda msg: True)
    assert result["status"] == "already_processed"


def test_skipped_processed_message_does_not_increment_attempts():
    item = entry()
    ledger = DeliveryLedgerRecord("ledger", metadata={"m1": "processed"})
    replay_dead_letter(item, "token-1", ledger, lambda msg: True)
    assert item.attempts == 0


def test_failed_dispatcher_records_failed_status():
    result = replay_dead_letter(entry(), "token-1", DeliveryLedgerRecord("ledger"), lambda msg: False)
    assert result["status"] == "failed"


def test_successful_dispatcher_marks_ledger_processed():
    ledger = DeliveryLedgerRecord("ledger")
    replay_dead_letter(entry(), "token-1", ledger, lambda msg: True)
    assert ledger.metadata["m1"] == "processed"


def test_exhausted_entry_is_not_dispatched():
    calls = []
    result = replay_dead_letter(entry(attempts=3), "token-1", DeliveryLedgerRecord("ledger"), lambda msg: calls.append(msg) or True)
    assert result["status"] == "exhausted" and calls == []


def test_custom_policy_changes_attempt_limit():
    svc = ReplayService(DeliveryLedgerRecord("ledger"), ReplayPolicyRecord("custom", metadata={"max_attempts": 1}))
    assert svc.replay(entry(attempts=1), "token-1", lambda msg: True)["status"] == "exhausted"


def test_message_id_is_passed_to_dispatcher():
    seen = []
    replay_dead_letter(entry("m9"), "token-1", DeliveryLedgerRecord("ledger"), lambda msg: seen.append(msg.identifier) or True)
    assert seen == ["m9"]


def test_common_wrong_fix_does_not_skip_failed_history():
    ledger = DeliveryLedgerRecord("ledger", metadata={"m1": "failed"})
    result = replay_dead_letter(entry(), "token-1", ledger, lambda msg: True)
    assert result["status"] == "replayed"
